changes.before:
function QueryState({ query, children, english = false }: { query: any; children: ReactNode; english?: boolean }) {
  return (
    <BaseQueryState
      english={english}
      query={
        query.error
          ? { ...query, error: { message: managementQueryError(query.error) } }
          : query
      }
    >
      {children}
    </BaseQueryState>
  );
}

