changes.before:
function DataTable({
  rows,
  columns,
  empty = "Todavía no hay registros",
  emptyDescription = "Revisa la búsqueda y los filtros, o registra un nuevo dato desde esta pantalla.",
}: {
  rows: any[];
  columns: Column[];
  empty?: string;
  emptyDescription?: string;
}) {
  const [page, setPage] = useState(1);
  useEffect(() => setPage(1), [rows.length]);
  const totalPages = Math.ceil(rows.length / 20);
  return rows.length ? (
    <>
      {/* G12: con desplazamiento horizontal, la tabla se recorre con teclado. */}
      <div className="table-wrap table-cards" tabIndex={0}>
        <table>
          <thead>
            <tr>
              {columns.map((c) => (
                <th key={c.label} className={c.className}>
                  {c.label.toUpperCase()}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {rows.slice((page - 1) * 20, page * 20).map((r, index) => (
              <tr key={r.id || r.sku || index}>
                {columns.map((c) => (
                  <td
                    key={c.label}
                    className={c.className}
                    data-label={c.label}
                  >
                    {c.render(r)}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {totalPages > 1 && (
        <div className="pagination">
          <span>
            {rows.length} registros · Página {page} de {totalPages}
          </span>
          <Button
            variant="ghost"
            disabled={page === 1}
            onClick={() => setPage(page - 1)}
          >
            Anterior
          </Button>
          <Button
            variant="ghost"
            disabled={page === totalPages}
            onClick={() => setPage(page + 1)}
          >
            Siguiente
          </Button>
        </div>
      )}
    </>
  ) : (
    <Empty title={empty} description={emptyDescription} />
  );
}

