            rows={rows}
            empty={ct("No encontramos productos")}
            emptyDescription={ct("Revisa los filtros o agrega un producto con Nuevo producto.")}
            columns={[
              {
                label: ct("Producto"),
                render: (p) => (
                  <div className="table-product">
                    <img
                      src={p.imageUrl || "/products/accessories.svg"}
