                    />
                    <div>
                      <strong>{p.name}</strong>
                      <small>
                        {p.sku} · {p.brand}
                      </small>
                    </div>
                  </div>
                ),
              },
              {
                label: ct("Categoría"),
                render: (p) => <Badge>{p.category.name}</Badge>,
              },
              { label: ct("Variantes"), render: (p) => p.variants.length },
              {
                label: ct("Precio"),
                render: (p) => formatMoney(p.variants[0]?.price || 0),
