              label: ct("Valores separados por coma"),
              initial: "S,M,L",
              required: true,
            },
            { key: "attribute2", label: ct("Segundo atributo"), initial: "color" },
            {
              key: "values2",
              label: ct("Valores separados por coma"),
              initial: "Negro,Azul",
            },
            requiredNumber("price", ct("Precio"), Number(matrix.variants[0].price)),
            requiredNumber(
              "costAvg",
              ct("Costo"),
              Number(matrix.variants[0].costAvg || 0),
            ),
          ]}
          onClose={() => setMatrix(null)}
          onSubmit={(values) =>
            post("/products/" + matrix.id + "/variants", {
              attributes: {
                [values.attribute1]: values.values1
                  .split(",")
